import { Inject, Injectable } from '@nestjs/common';
import type { Knex } from 'knex';
import type { Currency } from '../common/currency.js';
import { KNEX } from '../database/database.module.js';
import { isUniqueViolation } from '../database/unique-violation.js';
import { accountKey, type AccountRef, type OperationType } from './ledger.types.js';

const ACCOUNTS = 'accounts';
const OPERATIONS = 'operations';
const ENTRIES = 'entries';
const IDEMPOTENCY_KEY_UNIQUE = 'operations_idempotency_key_unique';

export interface NewUserAccount {
  /** UUID generated by the app. */
  id: string;
  userId: string;
  currency: Currency;
  createdAt: Date;
}

export interface NewOperation {
  id: string;
  type: OperationType;
  idempotencyKey: string;
  /** See `operationFingerprint`. */
  fingerprint: string;
  createdAt: Date;
}

export interface NewEntry {
  id: string;
  operationId: string;
  accountId: string;
  amount: bigint;
}

export const InsertOperationResult = {
  Created: 'created',
  KeyTaken: 'keyTaken',
} as const;

export type InsertOperationResult =
  (typeof InsertOperationResult)[keyof typeof InsertOperationResult];

export interface LockedAccount {
  id: string;
  type: AccountRef['type'];
  balance: bigint;
}

export interface StoredEntry {
  account: AccountRef;
  amount: bigint;
}

export interface StoredOperation {
  id: string;
  type: OperationType;
  fingerprint: string;
  createdAt: Date;
  entries: StoredEntry[];
}

export interface UserBalanceRecord {
  currency: Currency;
  balance: bigint;
}

interface AccountRow {
  id: string;
  type: AccountRef['type'];
  user_id: string | null;
  code: string | null;
  currency: Currency;
}

interface LockedAccountRow {
  id: string;
  type: AccountRef['type'];
  /** Text: mysql2 returns BIGINT as a JS number, which loses precision above 2^53. */
  balance: string;
}

interface OperationRow {
  id: string;
  type: OperationType;
  fingerprint: string;
  created_at: Date;
}

interface UserBalanceRow {
  currency: Currency;
  balance: string;
}

type StoredEntryRow = AccountRow & { amount: string };

@Injectable()
export class LedgerRepository {
  constructor(@Inject(KNEX) private readonly db: Knex) {}

  /**
   * Only for accounts that were not found: for an existing row the statement still takes a write lock.
   * Call it outside the posting transaction, so a failed posting does not roll the accounts back.
   */
  async ensureUserAccounts(accounts: readonly NewUserAccount[]): Promise<void> {
    if (accounts.length === 0) return;
    const tuples = accounts.map(() => "(?, 'user', ?, ?, 0, ?)").join(', ');
    const bindings = accounts.flatMap((a) => [a.id, a.userId, a.currency, a.createdAt]);
    // Not INSERT IGNORE: it would also turn a CHECK violation into a silent warning.
    await this.db.raw(
      `INSERT INTO ${ACCOUNTS} (id, type, user_id, currency, balance, created_at)
       VALUES ${tuples} ON DUPLICATE KEY UPDATE id = id`,
      bindings,
    );
  }

  /** Account ids by `accountKey`; a ref with no row is simply missing from the map. */
  async findAccountIds(refs: readonly AccountRef[]): Promise<Map<string, string>> {
    const users = refs.flatMap((ref) => (ref.type === 'user' ? [[ref.userId, ref.currency]] : []));
    const others = refs.flatMap((ref) =>
      ref.type === 'user' ? [] : [[ref.type, ref.code, ref.currency]],
    );
    const rows = (await this.db(ACCOUNTS)
      .select('id', 'type', 'user_id', 'code', 'currency')
      .where((q) => {
        if (users.length > 0) void q.whereIn(['user_id', 'currency'], users);
        if (others.length > 0) void q.orWhereIn(['type', 'code', 'currency'], others);
      })) as AccountRow[];
    return new Map(rows.map((row) => [accountKey(toAccountRef(row)), row.id]));
  }

  async transaction<T>(work: (tx: LedgerRepository) => Promise<T>): Promise<T> {
    return this.db.transaction((trx) => work(new LedgerRepository(trx)));
  }

  /** The unique index on the key is the idempotency guard: a taken key is reported, not thrown. */
  async insertOperation(operation: NewOperation): Promise<InsertOperationResult> {
    try {
      await this.db(OPERATIONS).insert({
        id: operation.id,
        type: operation.type,
        idempotency_key: operation.idempotencyKey,
        fingerprint: operation.fingerprint,
        created_at: operation.createdAt,
      });
      return InsertOperationResult.Created;
    } catch (error) {
      if (isUniqueViolation(error, IDEMPOTENCY_KEY_UNIQUE)) return InsertOperationResult.KeyTaken;
      throw error;
    }
  }

  /** Call inside `transaction`. Ascending id order: same accounts, same lock order. */
  async lockAccounts(ids: readonly string[]): Promise<LockedAccount[]> {
    const rows = (await this.db(ACCOUNTS)
      .select('id', 'type', this.db.raw('CAST(balance AS CHAR) AS balance'))
      .whereIn('id', ids)
      .orderBy('id')
      .forUpdate()) as LockedAccountRow[];
    return rows.map((row) => ({ id: row.id, type: row.type, balance: BigInt(row.balance) }));
  }

  async updateBalance(accountId: string, balance: bigint): Promise<void> {
    await this.db(ACCOUNTS).where({ id: accountId }).update({ balance: balance.toString() });
  }

  async insertEntries(entries: readonly NewEntry[]): Promise<void> {
    await this.db(ENTRIES).insert(
      entries.map((entry) => ({
        id: entry.id,
        operation_id: entry.operationId,
        account_id: entry.accountId,
        amount: entry.amount.toString(),
      })),
    );
  }

  async findOperationByKey(idempotencyKey: string): Promise<StoredOperation | undefined> {
    const operation = await this.db(OPERATIONS)
      .where({ idempotency_key: idempotencyKey })
      .first<OperationRow | undefined>('id', 'type', 'fingerprint', 'created_at');
    if (!operation) return undefined;

    const rows = await this.db(`${ENTRIES} as e`)
      .join(`${ACCOUNTS} as a`, 'a.id', 'e.account_id')
      .where('e.operation_id', operation.id)
      .select<StoredEntryRow[]>(
        'a.id',
        'a.type',
        'a.user_id',
        'a.code',
        'a.currency',
        this.db.raw('CAST(e.amount AS CHAR) AS amount'),
      );
    return {
      id: operation.id,
      type: operation.type,
      fingerprint: operation.fingerprint,
      createdAt: operation.created_at,
      entries: rows.map((row) => ({
        account: toAccountRef(row),
        amount: BigInt(row.amount),
      })),
    };
  }

  async readUserBalances(userId: string): Promise<UserBalanceRecord[]> {
    const rows = await this.db(ACCOUNTS)
      .where({ user_id: userId })
      .select<UserBalanceRow[]>('currency', this.db.raw('CAST(balance AS CHAR) AS balance'));
    return rows.map((row) => ({ currency: row.currency, balance: BigInt(row.balance) }));
  }
}

function toAccountRef(row: AccountRow): AccountRef {
  if (row.type === 'user') {
    return { type: 'user', userId: row.user_id ?? '', currency: row.currency };
  }
  return { type: row.type, code: row.code ?? '', currency: row.currency };
}
